styles/screens.css:
.lead-action-card { display: grid; gap: var(--space-5); padding: clamp(1.25rem, 4vw, 2.5rem); border: 1px solid var(--color-line); border-radius: var(--radius-large); background: var(--color-surface); box-shadow: var(--shadow-card); }
.lead-action-card h2 { margin-top: var(--space-3); margin-bottom: var(--space-2); font-family: var(--font-editorial); font-size: clamp(1.65rem, 5vw, 2.7rem); }
.lead-action-card p { max-width: 44rem; margin-bottom: 0; color: var(--color-muted); }
.feature-link-grid { display: grid; gap: var(--space-3); grid-template-columns: repeat(auto-fit, minmax(min(100%, 16rem), 1fr)); }
.feature-link-card { min-width: 0; min-height: 10rem; display: grid; align-content: start; gap: var(--space-2); padding: var(--space-5); border: 1px solid var(--color-line); border-radius: var(--radius-medium); background: var(--color-surface); text-decoration: none; transition: transform 160ms ease, box-shadow 160ms ease; }
.feature-link-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-card); }
.feature-link-card__number { color: var(--color-accent); font-family: var(--font-numeric); font-weight: 800; }
.feature-link-card strong { font-family: var(--font-editorial); font-size: 1.35rem; }
.feature-link-card span:last-child { color: var(--color-muted); }

@media (min-width: 48rem) {
  .lead-action-card { grid-template-columns: minmax(0, 1fr) auto; align-items: end; }
}
@media (forced-colors: active) {
  .primary-navigation__link.is-current, .button--primary, .app-brand__mark { border: 2px solid ButtonText; }
}
.record-form { display: grid; gap: var(--space-5); }
.subjective-details, .safety-details { display: grid; gap: var(--space-5); }
.home-summary-card__body { max-width: 48rem; }
@media (min-width: 42rem) {
  .field-grid--two, .two-column-layout, .home-two-column { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .field-grid--three { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .field-grid--four { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .next-action, .home-reading-card, .body-part-focus { grid-template-columns: minmax(0, 1fr) minmax(15rem, 0.7fr); align-items: center; }
  .next-action { grid-template-columns: minmax(0, 1fr) auto; }
}
@media (min-width: 64rem) {
  .field-grid--four { grid-template-columns: repeat(4, minmax(0, 1fr)); }
  .distribution-list { grid-template-columns: repeat(3, minmax(0, 1fr)); }
}
@media (max-width: 35rem) {
  .body-map { grid-template-columns: 1fr 1fr; }
  .body-map__view:last-child { grid-column: 1 / -1; width: 50%; justify-self: center; }
  .fact-grid { grid-template-columns: 1fr; }
  .fact-grid__wide { grid-column: auto; }
  .result-card__heading, .home-summary-card__header { display: grid; }
}
@media print {
  .form-submit-area, .screen-actions, .context-navigation, .text-link, .button { display: none !important; }
  .result-card, .home-summary-card, .home-compact-card, .daily-suggestion, .home-reading-card, .body-part-focus, .editorial-summary, .next-action { box-shadow: none; break-inside: avoid; }
}

@media (min-width: 48rem) {
  .history-item { grid-template-columns: minmax(9rem, 0.8fr) minmax(0, 2fr) auto; align-items: start; }
  .history-item__actions { flex-direction: column; align-items: stretch; min-width: 9rem; }
  .plan-candidate-grid { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .article-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media print {
  .app-header, .primary-navigation, .feature-menu, .screen-actions, .report-tabs, .button, .danger-zone, .data-management, .related-article, .context-navigation { display: none !important; }
  .share-report { border: 0; box-shadow: none; padding: 0; }
  .report-document, .report-textarea { border: 0; min-height: 0; padding: 0; background: transparent; }
  .screen--consultation .page-heading, .screen--consultation .next-action, .screen--consultation .safety-notice { break-inside: avoid; }
  .column-article { max-width: none; }
}
@media print {
  .consult-selector, .consult-mode-navigation, .plan-outcome-editor, .plan-edit-preview { display: none !important; }
}


















.check-option {
  min-height: 3rem;
  display: flex;
  align-items: flex-start;
  gap: var(--space-3);
  padding: var(--space-3);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-small);
  background: var(--color-surface);
}
.check-option:has(input:checked) {
  border-color: var(--color-selection-border);
  background: var(--color-selection-surface);
}
.check-option input {
  flex: 0 0 auto;
  width: 1.2rem;
  height: 1.2rem;
  min-height: 0;
  margin-top: 0.15rem;
  padding: 0;
}

















@media (min-width: 54rem) {





}
@media (forced-colors: active) {
  .check-option:has(input:checked){ border-color: CanvasText; }
}
@media print {




}



@media print {
  @page { size: A4 portrait; margin: 14mm; }
  body { background: white; }




}

/* ホーム・入力・結果の情報階層 */
.lead-action-card__actions,
.form-submit-actions,
.record-management-links > div:last-child,
.home-start-steps__links,
.home-record-overview__links {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  align-items: center;
}

.home-start-steps {
  display: grid;
  gap: var(--space-5);
  padding: clamp(1.1rem, 3vw, 2rem);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-large);
  background: var(--color-surface);
  box-shadow: var(--shadow-card);
}
.home-start-steps ol {
  display: grid;
  gap: var(--space-3);
  margin: 0;
  padding: 0;
  list-style: none;
}
.home-start-steps li {
  display: grid;
  grid-template-columns: 2.75rem minmax(0, 1fr);
  gap: var(--space-3);
  align-items: start;
  padding-block: var(--space-3);
  border-top: 1px solid var(--color-line);
}
.home-start-steps li > span {
  display: grid;
  width: 2.5rem;
  min-height: 2.5rem;
  place-items: center;
  border-radius: 999px;
  background: var(--color-accent-soft);
  color: var(--color-accent-strong);
  font-weight: 850;
}
.home-start-steps li strong { display: block; margin-bottom: var(--space-1); }
.home-start-steps li p { color: var(--color-muted); }

.home-record-overview {
  display: grid;
  gap: var(--space-4);
  padding: clamp(1.1rem, 3vw, 2rem);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-large);
  background: var(--color-surface);
  box-shadow: var(--shadow-card);
}
.home-record-overview > div:first-child > p:first-child,
.record-management-links > div:first-child > p:first-child {
  margin-bottom: var(--space-1);
  color: var(--color-accent);
  font-size: 0.75rem;
  font-weight: 850;
  letter-spacing: 0.12em;
}
.home-record-overview h2,
.record-management-links h2 {
  margin-bottom: var(--space-2);
  font-family: var(--font-editorial);
  font-size: clamp(1.25rem, 4vw, 1.8rem);
}
.home-record-overview__links { align-items: flex-start; flex-direction: column; }
.home-reading-card--compact { border-left: 5px solid var(--color-accent); }

.form-disclosure--profile { border-style: solid; }
.form-disclosure--optional { scroll-margin-top: 5rem; }
.form-disclosure summary .disclosure-status {
  flex: 0 0 auto;
  padding: 0.25rem 0.55rem;
  border-radius: 999px;
  background: var(--color-accent-soft);
  color: var(--color-accent-strong);
  font-size: 0.78rem;
  font-weight: 800;
}
.form-section--core { border-top: 5px solid var(--color-ink); }
.activity-type-choice { max-width: 34rem; }
.record-date-field { max-width: 20rem; }
.record-core-grid { grid-template-columns: repeat(auto-fit, minmax(min(100%, 11rem), 1fr)); }
.record-core-grid .field--range { grid-column: 1 / -1; }
.record-core-note { margin-top: var(--space-4); }
.record-optional-introduction {
  display: grid;
  gap: var(--space-2);
  padding: var(--space-4) 0 0;
}
.record-optional-introduction > p { color: var(--color-muted); }
.choice-grid--primary { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.choice-grid--detail { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.choice-card--attention { border-color: var(--color-attention-border); background: var(--color-attention-soft); }
.subjective-detail-type { display: grid; gap: var(--space-3); }
.subjective-detail-type fieldset { display: grid; gap: var(--space-3); }
.rest-entry-note {
  display: grid;
  gap: var(--space-3);
  padding: var(--space-4);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-medium);
  background: var(--color-accent-soft);
}
.rest-entry-note .field { max-width: 20rem; }
.record-memo-field {
  padding: clamp(1rem, 3vw, 1.5rem);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-medium);
  background: var(--color-surface);
}
.form-submit-area { grid-template-columns: minmax(0, 1fr) auto; align-items: center; }
.draft-status { min-height: 1.4em; margin-top: var(--space-2); color: var(--color-accent-strong); font-weight: 700; }
.record-management-links {
  display: grid;
  gap: var(--space-4);
  padding: clamp(1rem, 3vw, 1.5rem);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-medium);
  background: var(--color-surface);
}

.result-followup .feature-link-grid { grid-template-columns: repeat(auto-fit, minmax(min(100%, 13rem), 1fr)); }

@media (min-width: 48rem) {
  .home-start-steps ol { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .home-start-steps li { grid-template-columns: 2.75rem minmax(0, 1fr); border-top: 0; border-left: 1px solid var(--color-line); padding: var(--space-2) var(--space-4); }
  .home-start-steps li:first-child { border-left: 0; padding-left: 0; }
  .record-management-links { grid-template-columns: minmax(0, 1fr) auto; align-items: center; }
}

@media (max-width: 47.99rem) {
  .choice-grid--primary,
  .choice-grid--detail { grid-template-columns: 1fr; }
  .form-submit-area { grid-template-columns: 1fr; }
  .form-submit-actions { width: 100%; }
  .form-submit-actions .button { flex: 1 1 12rem; }
}

@media print {
  .home-start-steps__links,
  .record-management-links,
  .result-followup { display: none !important; }
}

/* レスポンシブ表示と印刷表示の統合 */
@media (min-width: 42rem) {
  .plan-flow-steps, .consult-flow-steps { grid-template-columns: repeat(3, minmax(0, 1fr)); }
  .share-format-picker, .plan-next-actions { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .consult-report-bridge { grid-template-columns: minmax(0, 1fr) auto; }
  .column-front-page__body { grid-template-columns: minmax(0, 1.5fr) minmax(15rem, 0.7fr); align-items: start; }
  .column-source-index__body article { grid-template-columns: minmax(0, 1fr) auto; align-items: start; }
}
@media (max-width: 35rem) {
  .page-heading-actions { justify-content: flex-start; margin-top: calc(var(--space-3) * -1); }
  .column-front-page__meta { display: grid; }
  .plan-candidate__heading { grid-template-columns: auto minmax(0, 1fr); }
  .plan-candidate__status-slot { grid-column: 1 / -1; justify-content: flex-start; }
}
@media print {
  .consult-flow-steps, .consult-selector, .consult-report-bridge, .page-heading-actions, .share-format-picker, .consult-draft-toolbar, .column-source-index, .plan-flow-steps { display: none !important; }
  .screen--share-report .share-report-document { border: 0; box-shadow: none; padding: 0; }
  .screen--share-report .report-document { font-size: 10pt; line-height: 1.45; }
}

/* プラン・相談共有・コラムの情報階層 */

/* 部位詳細・履歴・週次・終了の情報階層 */
.screen-boundary-note {
  padding: var(--space-4);
  border-left: 5px solid var(--color-line);
  background: var(--color-surface);
  color: var(--color-muted);
}
.numbered-detail-card {
  display: grid;
  grid-template-columns: 3rem minmax(0, 1fr);
  gap: var(--space-4);
  min-width: 0;
  padding: clamp(1rem, 4vw, 2rem);
  border: 1px solid var(--color-line);
  border-top: 5px solid var(--color-ink);
  border-radius: var(--radius-large);
  background: var(--color-surface);
  box-shadow: var(--shadow-card);
}
.numbered-detail-card__number {
  color: var(--color-accent);
  font-family: var(--font-numeric);
  font-size: 1.4rem;
  font-weight: 850;
}
.numbered-detail-card__content { min-width: 0; }
.body-part-position-layout {
  display: grid;
  gap: var(--space-5);
  align-items: center;
  margin-top: var(--space-4);
}
.body-part-name { display: grid; gap: var(--space-1); }
.body-part-name strong { font-family: var(--font-editorial); font-size: clamp(1.6rem, 5vw, 2.8rem); }
.body-part-name small { color: var(--color-muted); }
.related-body-parts,
.body-part-navigation {
  padding: var(--space-5);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-large);
  background: var(--color-surface);
}
.related-body-parts__links,
.body-part-navigation > div {
  display: grid;
  gap: 1px;
  background: var(--color-line);
}
.related-body-parts__links a,
.body-part-navigation__link {
  min-height: 3.25rem;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
  padding: var(--space-3) var(--space-4);
  background: var(--color-surface);
  text-decoration: none;
}
.body-part-navigation summary {
  min-height: 3rem;
  display: flex;
  align-items: center;
  cursor: pointer;
  font-weight: 850;
}
.body-part-navigation > div { margin-top: var(--space-3); }
.body-part-navigation__link small { color: var(--color-muted); }

.history-period-tabs,
.history-view-tabs {
  display: grid;
  gap: var(--space-2);
}
.history-period-tabs { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.history-period-tab,
.history-view-tab {
  min-height: 3rem;
  display: grid;
  place-items: center;
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-small);
  background: var(--color-surface);
  text-align: center;
  text-decoration: none;
  font-weight: 800;
}
.history-period-tab.is-current,
.history-view-tab.is-current {
  border-color: var(--color-accent);
  background: var(--color-accent-soft);
  color: var(--color-accent-strong);
}
.history-view-tab span { color: var(--color-muted); font-size: 0.78rem; font-weight: 500; }
.history-anchor-navigation,
.history-lead-card,
.history-week-bridge,
.weekly-next-action,
.finish-action-sheet {
  display: grid;
  gap: var(--space-4);
  align-items: center;
  padding: var(--space-5);
  border-left: 5px solid var(--color-accent);
  background: var(--color-accent-soft);
}
.history-anchor-navigation > div:first-child { display: grid; gap: var(--space-1); }
.history-anchor-navigation > div:first-child p,
.history-lead-card > div > p:first-child,
.history-week-bridge > div > p:first-child,
.weekly-next-action > div > p:first-child,
.finish-action-sheet > div > p:first-child {
  margin: 0;
  color: var(--color-accent);
  font-size: 0.75rem;
  font-weight: 850;
  letter-spacing: 0.12em;
}
.history-anchor-navigation > div:last-child,
.weekly-navigation {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}
.history-count-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1px;
  margin: 0;
  border: 1px solid var(--color-line);
  background: var(--color-line);
}
.history-count-grid > div { min-width: 0; padding: var(--space-3); background: var(--color-surface); }
.history-count-grid dt { color: var(--color-muted); font-size: 0.78rem; font-weight: 800; }
.history-count-grid dd { margin: var(--space-1) 0 0; font-family: var(--font-numeric); font-size: 1.4rem; font-weight: 850; }
.history-bar-chart {
  min-height: 15rem;
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(2.4rem, 1fr);
  gap: var(--space-2);
  align-items: end;
  overflow-x: auto;
  padding: var(--space-4) 0;
  border-bottom: 1px solid var(--color-line);
}
.history-bar-chart__column {
  min-height: 12rem;
  display: grid;
  grid-template-rows: auto 8rem auto;
  gap: var(--space-1);
  align-items: end;
  justify-items: center;
  color: var(--color-muted);
  font-size: 0.72rem;
}
.history-bar-chart__bar {
  width: min(1.5rem, 70%);
  height: var(--history-bar);
  min-height: 0;
  align-self: end;
  border-radius: 0.4rem 0.4rem 0 0;
  background: var(--color-accent);
}
.history-bar-chart__column--rest .history-bar-chart__bar { background: var(--color-line); }
.history-bar-chart__column--missing .history-bar-chart__bar { height: 0; border: 0; }
.history-calendar,
.weekly-day-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 7.5rem), 1fr));
  gap: var(--space-2);
  margin: 0;
  padding: 0;
  list-style: none;
}
.history-calendar__day,
.weekly-day-card {
  min-width: 0;
  display: grid;
  gap: var(--space-2);
  padding: var(--space-3);
  border-top: 4px solid var(--color-line);
  background: var(--color-surface);
}
.history-calendar__day--run,
.weekly-day-card--run { border-top-color: var(--color-accent); }
.history-calendar__day--rest,
.weekly-day-card--rest { border-top-color: var(--color-rest); }
.history-calendar__day a,
.weekly-day-card a { font-weight: 800; }
.subjective-coverage,
.weekly-load-comparison {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 1px;
  background: var(--color-line);
}
.subjective-coverage > div,
.weekly-load-comparison > div {
  display: grid;
  gap: var(--space-1);
  padding: var(--space-4);
  background: var(--color-surface);
}
.subjective-coverage strong,
.weekly-load-comparison strong { font-family: var(--font-editorial); font-size: 1.8rem; }
.compact-link-list { display: grid; gap: var(--space-2); padding-left: 1.25rem; }
.history-distribution-layout { display: grid; gap: var(--space-5); align-items: start; }
.history-body-part-selector { display: grid; gap: var(--space-3); align-items: end; }
.history-series,
.history-timeline {
  display: grid;
  gap: var(--space-2);
  margin: 0;
  padding: 0;
  list-style: none;
}
.history-series li { display: grid; grid-template-columns: 4.2rem minmax(6rem, 1fr) 4.5rem; gap: var(--space-3); align-items: center; }
.history-series__track { height: 0.7rem; background: var(--color-line); }
.history-series__track > span { display: block; width: var(--series-width); height: 100%; background: var(--color-accent); }
.history-timeline li { display: grid; grid-template-columns: 8rem auto minmax(0, 1fr); gap: var(--space-3); align-items: center; padding-block: var(--space-2); border-bottom: 1px solid var(--color-line); }
.history-timeline p { margin: 0; }
.course-group-list,
.weekly-plan-list { display: grid; gap: var(--space-3); }
.course-group-list article,
.weekly-plan-list article { padding: var(--space-4); border: 1px solid var(--color-line); background: var(--color-surface); }
.course-group-list dl { display: grid; gap: var(--space-2); margin: 0; }
.course-group-list dl > div { display: flex; justify-content: space-between; gap: var(--space-3); }
.course-group-list dd { margin: 0; font-weight: 800; }
.history-record-browser { display: grid; gap: var(--space-4); }
.history-basic-layout,
.history-detail-layout { display: grid; gap: var(--space-5); }
.weekly-period-heading { padding-block: var(--space-4); border-block: 5px double var(--color-ink); }
.weekly-period-heading h2 { margin-bottom: var(--space-2); font-family: var(--font-editorial); font-size: clamp(1.8rem, 6vw, 3.4rem); }
.weekly-day-card > div:first-child { display: flex; justify-content: space-between; gap: var(--space-2); color: var(--color-muted); font-weight: 800; }
.weekly-day-card p,
.weekly-day-card small { margin: 0; color: var(--color-muted); }
.weekly-plan-list article > div:first-child { display: flex; flex-wrap: wrap; justify-content: space-between; gap: var(--space-2); }
.finish-state-sheet,
.finish-closed-card,
.finish-data-tools {
  display: grid;
  gap: var(--space-4);
  padding: clamp(1.1rem, 4vw, 2rem);
  border: 1px solid var(--color-line);
  background: var(--color-surface);
  box-shadow: var(--shadow-card);
}
.finish-action-stack { display: grid; gap: var(--space-2); }
.finish-closed-card { justify-items: start; border-block: 6px solid var(--color-ink); }
.finish-closed-card__mark { display: grid; place-items: center; width: 3.5rem; height: 3.5rem; border-radius: 50%; background: var(--color-accent); color: var(--color-on-accent); font-size: 2rem; font-weight: 900; }
.finish-closed-card > h2 { font-family: var(--font-editorial); font-size: clamp(1.8rem, 6vw, 3.5rem); }
.finish-data-tools > summary { min-height: 3rem; display: flex; align-items: center; cursor: pointer; font-weight: 850; }
.finish-data-tools__body { display: grid; gap: var(--space-5); padding-top: var(--space-4); border-top: 1px solid var(--color-line); }

@media (min-width: 42rem) {
  .body-part-position-layout,
  .history-distribution-layout { grid-template-columns: minmax(0, 1.25fr) minmax(14rem, 0.75fr); }
