.history-calendar-block,
.history-chart-block {
  display: grid;
  gap: var(--space-4);
  min-width: 0;
}
.history-calendar-legend,
.history-chart-key {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2) var(--space-4);
  align-items: center;
  color: var(--color-muted);
  font-size: 0.82rem;
  font-weight: 750;
}
.history-calendar-legend > span,
.history-chart-key > span {
  display: inline-flex;
  gap: var(--space-1);
  align-items: center;
}
.history-calendar-legend__symbol,
.history-calendar-legend__selected,
.history-chart-key__rest,
.history-chart-key__missing {
  display: inline-grid;
  place-items: center;
  width: 1.25rem;
  height: 1.25rem;
  flex: 0 0 auto;
}
.history-calendar-legend__symbol--run { color: var(--color-accent); }
.history-calendar-legend__symbol--rest { color: var(--color-rest); }
.history-calendar-legend__symbol--missing { color: var(--color-muted); }
.history-calendar-legend__symbol--subjective { color: var(--color-info); }
.history-calendar-legend__selected {
  border: 3px double var(--color-ink);
  background: var(--color-paper);
}
.history-calendar-scroll,
.history-chart-scroll {
  min-width: 0;
  overflow-x: auto;
  overflow-y: hidden;
  padding: var(--space-2);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-medium);
  background: var(--color-paper);
  overscroll-behavior-inline: contain;
  scrollbar-gutter: stable;
}
.history-calendar-scroll:focus-visible,
.history-chart-scroll:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 3px;
}
.history-calendar-weekdays,
.history-calendar {
  min-width: 42rem;
  display: grid;
  grid-template-columns: repeat(7, minmax(5.25rem, 1fr));
  gap: var(--space-2);
}
.history-calendar-weekdays {
  margin-bottom: var(--space-2);
  color: var(--color-muted);
  font-size: 0.78rem;
  font-weight: 850;
  text-align: center;
}
.history-calendar {
  align-items: stretch;
  margin: 0;
  padding: 0;
  list-style: none;
}
.history-calendar__day:first-child { grid-column-start: var(--calendar-start, 1); }
.history-calendar__day {
  min-width: 0;
  min-height: 8.25rem;
  padding: 0;
  border: 1px solid var(--color-line);
  border-top-width: 5px;
  border-radius: var(--radius-medium);
  background: var(--color-surface);
}
.history-calendar__day--run { border-top-color: var(--color-accent); }
.history-calendar__day--rest { border-top-color: var(--color-rest); }
.history-calendar__day--missing { border-top-color: var(--color-line-strong); }
.history-calendar__day.has-subjective { box-shadow: inset 0 -4px 0 var(--color-info); }
.history-calendar__day.is-selected {
  outline: 3px double var(--color-ink);
  outline-offset: 2px;
}
.history-calendar__day-content {
  min-height: 100%;
