  align-content: start;
  gap: var(--space-2);
  padding: var(--space-3);
  color: inherit;
  text-decoration: none;
}
a.history-calendar__day-content:hover { background: var(--color-accent-soft); }
a.history-calendar__day-content:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: -3px;
}
.history-calendar__date {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: var(--space-1);
  color: var(--color-muted);
  font-size: 0.78rem;
  font-weight: 850;
}
.history-calendar__selected-label {
  color: var(--color-ink);
  font-size: 0.7rem;
}
.history-calendar__status {
  display: flex;
