  align-items: center;
}
.history-calendar__status-symbol { color: var(--color-muted); }
.history-calendar__day--run .history-calendar__status-symbol { color: var(--color-accent); }
.history-calendar__day--rest .history-calendar__status-symbol { color: var(--color-rest); }
.history-calendar__subjective,
.history-calendar__plan {
  color: var(--color-muted);
  font-size: 0.72rem;
  line-height: 1.45;
}
.history-calendar__subjective > span { color: var(--color-info); }
.history-chart-summary {
  max-width: var(--reading-width);
  margin: 0;
  color: var(--color-muted);
}
.history-chart-scroll svg {
  display: block;
  max-width: none;
  overflow: visible;
  font-family: var(--font-numeric);
}
.history-chart__grid line {
  stroke: var(--color-line);
  stroke-width: 1;
  vector-effect: non-scaling-stroke;
}
.history-chart__grid text,
.history-chart__date-label,
.history-chart__rest-label {
  fill: var(--color-muted);
  font-size: 11px;
  font-weight: 750;
}
.history-chart__line {
  fill: none;
  stroke: var(--color-accent);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;
  vector-effect: non-scaling-stroke;
}
.history-chart__run-marker { fill: var(--color-accent); stroke: var(--color-paper); stroke-width: 2; }
.history-chart__rest-marker,
.history-chart__rest-column { fill: var(--color-rest); }
.history-chart__day--missing path {
  fill: none;
  stroke: var(--color-muted);
  stroke-width: 2;
  vector-effect: non-scaling-stroke;
}
.history-chart__hit-target { fill: transparent; pointer-events: all; }
.history-chart__selected-column {
  fill: color-mix(in srgb, var(--color-accent-soft) 54%, transparent);
  stroke: var(--color-ink);
  stroke-width: 2;
  stroke-dasharray: 5 4;
  vector-effect: non-scaling-stroke;
  pointer-events: none;
}
.history-chart__focus-ring,
.history-chart__focus-column {
