.history-chart__day-link:focus .history-chart__focus-column,
.history-chart__day-link:focus-visible .history-chart__focus-ring,
.history-chart__day-link:focus-visible .history-chart__focus-column { stroke: var(--color-focus); }
.history-chart-key__line {
  width: 1.7rem;
  height: 0;
  border-top: 3px solid var(--color-accent);
}
.history-chart-key__rest {
  width: 0.8rem;
  height: 0.8rem;
  background: var(--color-rest);
}
.history-chart-key__missing { font-weight: 900; }
.history-stacked-chart__segment {
  stroke: var(--color-paper);
  stroke-width: 0.75;
  vector-effect: non-scaling-stroke;
}
.history-part-tone--0 { fill: var(--color-accent); background: var(--color-accent); }
.history-part-tone--1 { fill: var(--color-info); background: var(--color-info); }
.history-part-tone--2 { fill: var(--color-model); background: var(--color-model); }
.history-part-tone--3 { fill: var(--color-rest); background: var(--color-rest); }
.history-part-tone--4 { fill: color-mix(in srgb, var(--color-accent) 70%, var(--color-paper)); background: color-mix(in srgb, var(--color-accent) 70%, var(--color-paper)); }
.history-part-tone--5 { fill: color-mix(in srgb, var(--color-info) 70%, var(--color-paper)); background: color-mix(in srgb, var(--color-info) 70%, var(--color-paper)); }
.history-part-tone--6 { fill: color-mix(in srgb, var(--color-model) 70%, var(--color-paper)); background: color-mix(in srgb, var(--color-model) 70%, var(--color-paper)); }
.history-part-tone--7 { fill: var(--color-muted); background: var(--color-muted); }
.history-part-tone--8 { fill: var(--color-ink); background: var(--color-ink); }
.history-part-legend {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(9rem, 1fr));
  gap: var(--space-2);
  margin: 0;
  padding: 0;
  list-style: none;
}
.history-part-legend li { min-width: 0; }
.history-part-legend li > :is(a, span) {
  min-height: var(--touch-target);
  display: flex;
  gap: var(--space-2);
  align-items: center;
  padding: var(--space-2);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-small);
  color: inherit;
  text-decoration: none;
}
.history-part-legend li.is-selected > :is(a, span) {
  border-width: 2px;
  border-color: var(--color-ink);
  background: var(--color-paper);
}
.history-part-legend a:hover { background: var(--color-accent-soft); }
.history-part-legend a:focus-visible { outline: 3px solid var(--color-focus); outline-offset: 2px; }
.history-part-legend__swatch {
  width: 1.65rem;
  height: 1.65rem;
  display: inline-grid;
  place-items: center;
  flex: 0 0 auto;
  border: 1px solid var(--color-line-strong);
  color: var(--color-paper);
  font-size: 0.72rem;
  font-weight: 900;
}
.history-part-legend__swatch > span { filter: drop-shadow(0 1px 1px rgba(0, 0, 0, 0.55)); }
.history-chart-data {
  border-top: 1px solid var(--color-line);
  padding-top: var(--space-3);
}
.history-chart-data > summary {
  min-height: var(--touch-target);
  display: flex;
  align-items: center;
  cursor: pointer;
  font-weight: 850;
}
.history-chart-data tr.is-selected { outline: 2px solid var(--color-ink); outline-offset: -2px; }
@media (max-width: 35rem) {
  .history-calendar-weekdays,
  .history-calendar { min-width: 38rem; grid-template-columns: repeat(7, minmax(4.75rem, 1fr)); }
  .history-calendar__day { min-height: 7.75rem; }
  .history-part-legend { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}
@media (forced-colors: active) {
  .history-calendar__day,
  .history-calendar__day.is-selected,
  .history-calendar-legend__selected,
  .history-part-legend li > :is(a, span) { border-color: CanvasText; }
  .history-calendar__day.has-subjective { box-shadow: inset 0 -4px 0 CanvasText; }
  .history-chart__line,
  .history-chart__grid line,
  .history-chart__day--missing path,
  .history-chart__selected-column,
  .history-chart__focus-ring,
  .history-chart__focus-column { stroke: CanvasText; }
  .history-chart__run-marker,
  .history-chart__rest-marker,
  .history-chart__rest-column,
  .history-stacked-chart__segment,
  .history-part-legend__swatch { fill: CanvasText; background: CanvasText; }
  .history-chart__hit-target { fill: transparent; }
}
@media print {
  .history-calendar-scroll,
  .history-chart-scroll {
    overflow: visible;
    padding: 0;
    border: 0;
  }
  .history-calendar-weekdays,
  .history-calendar { min-width: 0; }
  .history-calendar__day { min-height: 0; break-inside: avoid; }
  .history-chart-scroll svg { width: 100%; height: auto; max-width: 100%; }
  .history-chart-data > summary { display: none !important; }
  .history-chart-data > :not(summary) { display: block !important; }
  .history-part-legend a { color: inherit; text-decoration: none; }
}

/* 履歴可視化の操作高さ調整 */
.history-part-legend li > :is(a, span),
.history-chart-data > summary { min-height: 45px; }
@media print {
  .history-calendar-weekdays,
  .history-calendar {
    min-width: 0;
    grid-template-columns: repeat(7, minmax(0, 1fr));
    gap: 2px;
  }
  .history-calendar__day-content { padding: 3px; }
  .history-calendar__date,
  .history-calendar__subjective,
  .history-calendar__plan { font-size: 7pt; }
  .history-calendar__status { display: grid; gap: 1px; }
}


/* UI-FEEDBACK2: first-run plan empty state */
.plan-empty-start {
  display: grid;
  gap: var(--space-5);
  padding: clamp(1.1rem, 3vw, 2rem);
  border: 1px solid var(--color-line);
  border-left: 5px solid var(--color-accent);
  border-radius: var(--radius-large);
  background: var(--color-surface);
  box-shadow: var(--shadow-card);
}
.plan-empty-start h2 {
  margin: var(--space-2) 0 0;
  font-family: var(--font-editorial);
  font-size: clamp(1.45rem, 5vw, 2.35rem);
}
.plan-empty-start p {
  margin: var(--space-2) 0 0;
  color: var(--color-muted);
}
.plan-empty-actions {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));
  gap: var(--space-3);
}
.plan-empty-actions .feature-link-card {
  min-height: 8.5rem;
  color: inherit;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

/* 5段階プラン比較とコース条件表示 */
.plan-flow-steps--five small {
  grid-column: 2;
  color: var(--color-muted);
  font-size: 0.78rem;
}
.plan-stage {
  display: grid;
  gap: var(--space-4);
  min-width: 0;
  scroll-margin-top: 5rem;
}
.plan-reference-card,
.plan-model-summary,
.plan-body-map-reference,
.plan-stage--confirm {
  min-width: 0;
  padding: clamp(1rem, 3vw, 1.75rem);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-large);
  background: var(--color-surface);
  box-shadow: var(--shadow-card);
}
.plan-reference-card {
  display: grid;
  gap: var(--space-4);
  border-top: 5px solid var(--color-ink);
}
.plan-load-summary {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: var(--space-1) var(--space-3);
  align-items: end;
  padding: var(--space-4);
  border: 1px solid var(--color-line);
  border-left: 5px solid var(--color-accent);
  background: var(--color-accent-soft);
}
.plan-load-summary > span {
  color: var(--color-muted);
  font-size: 0.82rem;
  font-weight: 800;
  letter-spacing: 0.05em;
}
.plan-load-summary > strong {
  grid-row: 1 / span 2;
  grid-column: 2;
  font-family: var(--font-numeric);
  font-size: clamp(1.65rem, 4.4vw, 2.65rem);
  font-weight: 760;
  line-height: 1;
  letter-spacing: -0.02em;
}
.plan-load-summary > small {
  color: var(--color-muted);
  font-weight: 700;
  line-height: 1.45;
}
.plan-change-summary {
  margin: 0;
  color: var(--color-muted);
}
.plan-condition-summary {
  display: grid;
  gap: 1px;
  min-width: 0;
  margin: 0;
  border: 1px solid var(--color-line);
  background: var(--color-line);
}
.plan-condition-row {
  min-width: 0;
  display: grid;
  grid-template-columns: minmax(5.5rem, 0.7fr) minmax(0, 1.3fr);
  gap: var(--space-3);
  align-items: center;
  padding: var(--space-3);
  background: var(--color-surface);
}
.plan-condition-row dt {
  color: var(--color-muted);
  font-size: 0.78rem;
  font-weight: 800;
}
.plan-condition-row dd {
  min-width: 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  gap: var(--space-2);
  margin: 0;
}
.plan-condition-row dd strong {
  min-width: 0;
  overflow-wrap: anywhere;
}
.plan-condition-row--same {
  box-shadow: inset 4px 0 0 var(--color-line-strong);
}
.plan-condition-row--changed {
  box-shadow: inset 4px 0 0 var(--color-accent);
}
.plan-condition-status {
  flex: 0 0 auto;
  align-self: center;
  padding: 0.2rem 0.5rem;
  border: 1px solid var(--color-line);
  border-radius: 999px;
  color: var(--color-muted);
  background: var(--color-paper);
  font-size: 0.72rem;
  font-weight: 850;
}
.plan-condition-status--changed {
  border-color: color-mix(in srgb, var(--color-accent) 48%, var(--color-line));
  color: var(--color-accent-strong);
  background: var(--color-accent-soft);
}
.plan-candidate {
  align-content: start;
}
.plan-candidate .plan-condition-summary {
  align-self: stretch;
}
.plan-candidate .plan-condition-row {
  grid-template-columns: minmax(5rem, 0.75fr) minmax(0, 1.25fr);
}
.plan-candidate > .button {
  align-self: end;
  width: 100%;
}
.plan-edit-group {
  display: grid;
  gap: var(--space-4);
  min-width: 0;
  margin: 0;
  padding: clamp(1rem, 3vw, 1.5rem);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-medium);
  background: var(--color-surface-warm);
}
.plan-edit-group + .plan-edit-group {
  margin-top: var(--space-5);
}
.plan-edit-group legend {
  padding-inline: var(--space-2);
  font-family: var(--font-editorial);
  font-size: 1.25rem;
  font-weight: 850;
}
.plan-edit-group--course {
  border-top: 5px solid var(--color-ink);
}
.plan-surface-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: var(--space-3);
}
.plan-model-layout {
  display: grid;
  gap: var(--space-4);
  align-items: start;
}
.plan-model-summary,
.plan-body-map-reference {
  display: grid;
  gap: var(--space-4);
}
.plan-body-map-reference {
  background: var(--color-paper);
}
.plan-body-map-reference h3 {
  font-family: var(--font-editorial);
  font-size: 1.5rem;
}
.plan-body-map-reference .body-map__view svg {
  max-height: 17rem;
}
.plan-body-map-rest {
  padding: var(--space-4);
  border: 1px dashed var(--color-line);
  background: var(--color-surface);
}
.plan-final-heading {
  display: grid;
  gap: 1px;
  background: var(--color-line);
}
.plan-final-heading > div {
  display: grid;
  gap: var(--space-1);
  padding: var(--space-3) var(--space-4);
  background: var(--color-surface);
}
.plan-final-heading span,
.saved-plan-conditions dt {
  color: var(--color-muted);
  font-size: 0.78rem;
  font-weight: 800;
}
.saved-plan-conditions {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 9rem), 1fr));
  gap: 1px;
  margin: 0;
  border: 1px solid var(--color-line);
  background: var(--color-line);
}
.saved-plan-conditions > div {
  min-width: 0;
  padding: var(--space-3);
  background: var(--color-surface);
}
.saved-plan-conditions dd {
  margin: var(--space-1) 0 0;
  overflow-wrap: anywhere;
  font-weight: 800;
}
.plan-save-complete .plan-condition-status {
  display: none;
}
@media (min-width: 42rem) {
  .plan-flow-steps--five {
    grid-template-columns: repeat(5, minmax(0, 1fr));
  }
  .plan-condition-summary {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .plan-final-heading {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .plan-surface-grid {
    grid-template-columns: repeat(4, minmax(0, 1fr));
  }
}
@media (min-width: 64rem) {
  .plan-candidate-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }
  .plan-candidate__copy h3 {
    min-block-size: 2.8em;
  }
  .plan-candidate__copy > p:last-child {
    min-block-size: 3.6em;
  }
  .plan-model-layout {
    grid-template-columns: minmax(0, 1.15fr) minmax(20rem, 0.85fr);
  }
}
@media (min-width: 48rem) and (max-width: 63.99rem) {
  .plan-candidate-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 35rem) {
  .plan-condition-row,
  .plan-candidate .plan-condition-row {
    grid-template-columns: 1fr;
    gap: var(--space-1);
  }
  .plan-condition-row dd {
    align-items: center;
  }
  .plan-surface-grid {
    grid-template-columns: 1fr;
  }
  .plan-load-summary {
    grid-template-columns: 1fr;
  }
  .plan-load-summary > strong {
    grid-row: auto;
    grid-column: auto;
  }
}
@media (forced-colors: active) {
  .plan-condition-row--same,
  .plan-condition-row--changed,
  .plan-load-summary,
  .plan-stage--confirm,
  .plan-reference-card {
    border: 2px solid ButtonText;
    box-shadow: none;
  }
  .plan-condition-status--changed {
    border: 2px solid Highlight;
  }
}
@media print {
  .plan-stage--candidates .button,
  .plan-stage--edit,
  .plan-stage--confirm .form-submit-area,
  .saved-plan__actions,
  .plan-outcome-editor {
    display: none !important;
  }
  .plan-reference-card,
  .plan-model-summary,
  .plan-body-map-reference,
  .plan-stage--confirm,
  .plan-candidate,
  .saved-plan {
    break-inside: avoid;
    box-shadow: none;
  }
}

/* 相談メモ、印刷、PDF向け表示 */
.consult-entry-grid {
  display: grid;
  gap: var(--space-4);
}
.consult-entry-card {
  min-width: 0;
  min-height: 16rem;
  display: grid;
  align-content: start;
  gap: var(--space-3);
  padding: clamp(1.25rem, 4vw, 2.25rem);
  border: 2px solid var(--color-line-strong);
  border-radius: var(--radius-large);
  background: var(--color-surface);
  box-shadow: var(--shadow-card);
  color: inherit;
  text-decoration: none;
}
.consult-entry-card--quick { border-top: 7px solid var(--color-accent); }
.consult-entry-card--report { border-top: 7px solid var(--color-ink); }
.consult-entry-card > span {
