}
.consult-priority-report h2 { margin-block: var(--space-1); }
.consult-priority-report p { margin: 0; }
@media (min-width: 48rem) {
  .consult-priority-report { grid-template-columns: minmax(0, 1fr) auto; }
}

.consult-draft-toolbar {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-3);
}
.consult-draft-toolbar > div {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
}
.report-screen-tools {
  display: grid;
  gap: var(--space-6);
}
.report-print-actions {
  display: grid;
  gap: var(--space-4);
  align-items: center;
  padding: clamp(1rem, 4vw, 1.75rem);
  border: 2px solid var(--color-accent);
  border-radius: var(--radius-large);
  background: var(--color-accent-soft);
}
.report-print-actions h2 { margin-bottom: var(--space-2); }
.report-print-actions p:last-child { margin-bottom: 0; color: var(--color-muted); }
.report-copy-source {
  position: fixed;
  inline-size: 1px;
