  font-size: 0.72rem;
  font-weight: 850;
  letter-spacing: 0.1em;
}
.report-sheet__title {
  margin-block: var(--space-1);
  font-family: var(--font-editorial);
  font-size: clamp(2rem, 7vw, 4rem);
