}
.report-fact-list dt,
.report-notes-list dt {
  color: var(--color-muted);
  font-size: 0.75rem;
  font-weight: 850;
}
.report-fact-list dd,
.report-notes-list dd {
  margin: var(--space-1) 0 0;
  overflow-wrap: anywhere;
  font-weight: 750;
}
.report-free-note {
