  border: 1px solid var(--color-line);
  background: var(--color-surface);
}
.report-free-note p { margin: var(--space-2) 0 0; white-space: pre-wrap; }
.report-model-total {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: var(--space-2) var(--space-4);
  align-items: center;
  padding: var(--space-4);
  border-left: 7px solid var(--color-accent);
  background: var(--color-accent-soft);
}
.report-model-total > span { color: var(--color-muted); font-weight: 850; }
.report-model-total > strong {
  grid-row: 1 / span 2;
  grid-column: 2;
  font-family: var(--font-numeric);
  font-size: clamp(2rem, 7vw, 3.8rem);
  font-weight: 800;
  line-height: 1;
  letter-spacing: -0.02em;
}
.report-model-total > p { margin: 0; color: var(--color-muted); }
.report-body-map {
  min-width: 0;
  padding: var(--space-3);
  border: 1px solid var(--color-line);
  background: var(--color-paper);
}
.report-body-map .body-map__view svg { max-height: 15rem; }
.report-chart-panel {
  min-width: 0;
  display: grid;
  gap: var(--space-3);
  padding: var(--space-4);
  border: 1px solid var(--color-line);
  background: var(--color-paper);
}
.report-chart-panel h3 { font-family: var(--font-editorial); font-size: 1.3rem; }

.report-period-summary {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 1px;
  overflow: hidden;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-medium);
  background: var(--color-line);
}
.report-period-summary > div {
  display: grid;
  gap: var(--space-1);
  padding: var(--space-3);
  background: var(--color-surface);
}
.report-period-summary strong {
  font-family: var(--font-numeric);
  font-size: clamp(1.25rem, 4vw, 1.8rem);
  line-height: 1;
}
.report-period-summary span { color: var(--color-muted); font-weight: 750; }
.report-chart-panel--printable {
