  border: 1px solid var(--color-line);
  background: var(--color-surface);
  color: var(--color-muted);
}
.report-period-table {
  inline-size: 100%;
  border-collapse: collapse;
  table-layout: fixed;
  background: var(--color-surface);
}
.report-period-table th,
.report-period-table td {
  padding: var(--space-2) var(--space-3);
  border: 1px solid var(--color-line);
  text-align: left;
  vertical-align: top;
  overflow-wrap: anywhere;
}
.report-period-table th {
  color: var(--color-muted);
  font-size: 0.76rem;
  font-weight: 850;
}
.report-print-note {
  margin: 0;
  color: var(--color-muted);
}
.report-sheet__boundary {
  padding: var(--space-4);
  border-top: 3px solid var(--color-ink);
  background: var(--color-paper);
}
.report-sheet__boundary p { margin: var(--space-2) 0 0; color: var(--color-muted); }
@media (min-width: 48rem) {
  .consult-entry-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }
  .report-print-actions { grid-template-columns: minmax(0, 1fr) auto; }
}
@media (max-width: 35rem) {
  .report-fact-list,
  .report-notes-list,
  .report-period-summary { grid-template-columns: 1fr; }
  .report-model-total { grid-template-columns: 1fr; }
  .report-model-total > strong { grid-row: auto; grid-column: auto; }
  .report-sheet__header { display: grid; }
}
@media (forced-colors: active) {
  .consult-entry-card,
  .report-print-actions,
  .report-section--subjective,
  .report-model-total,
  .report-sheet { border: 2px solid CanvasText; box-shadow: none; }
  .consult-entry-card[href]:focus-visible { outline: 3px solid Highlight; }
}
@media print {
  @page { size: A4 portrait; margin: 12mm; }
  body { background: white !important; }
  .screen--share-report > .page-heading,
  .screen--share-report > .page-heading-actions,
  .report-screen-tools,
  .report-copy-source { display: none !important; }
  .screen--share-report,
  .report-output-area {
    display: block;
    padding: 0;
    margin: 0;
    background: white;
  }
  .report-sheet {
    max-width: none;
    gap: 4mm;
    padding: 0;
    border: 0;
    box-shadow: none;
    color: black;
    background: white;
  }
  .report-sheet--standard {
    font-size: 9.3pt;
    line-height: 1.28;
  }
  .report-sheet--standard .report-sheet__title { font-size: 25pt; }
  .report-sheet--standard .report-section,
  .report-sheet--standard .report-period-section { gap: 2.5mm; padding-top: 2.5mm; }
  .report-sheet--standard .report-section--subjective { padding: 3mm; }
  .report-sheet--standard .report-fact-list > div,
  .report-sheet--standard .report-notes-list > div,
  .report-sheet--standard .report-model-total,
  .report-sheet--standard .report-body-map,
  .report-sheet--standard .report-sheet__boundary { padding: 2.5mm; }
  .report-sheet--standard .report-body-map .body-map__view svg { max-height: 47mm; }
  .report-sheet--standard .report-model-total > strong { font-size: 26pt; }
  .report-print-line-chart { max-height: 42mm; }
  .report-period-table th,
  .report-period-table td { padding: 1.5mm 2mm; font-size: 8.5pt; }
  .report-period-summary > div { padding: 2mm; }
  .report-print-note { font-size: 8.5pt; }
  .report-sheet__header,
  .report-section,
  .report-fact-list > div,
  .report-model-total,
  .report-body-map,
  .report-sheet__boundary,
  .report-chart-panel { break-inside: avoid; }
  .report-sheet--detailed .report-period-section { break-before: page; }
}

/* 文字拡大時の表示保護。
   Keeps wide history graphics inside their local scrollers and allows plan text
   to wrap without expanding the page when text size is increased. */
.screen {
  min-width: 0;
  grid-template-columns: minmax(0, 1fr);
}
.screen > *,
.history-basic-layout,
.history-detail-layout,
.history-chart-block,
.plan-flow-steps,
.plan-flow-steps > li,
.plan-stage,
.plan-stage > *,
.plan-condition-summary,
.plan-condition-row,
.field-grid,
.field-grid > * {
  min-width: 0;
  max-width: 100%;
}
.plan-flow-steps :is(strong, small),
.plan-condition-row :is(dt, dd, strong, small) {
  overflow-wrap: anywhere;
}
@media (min-width: 42rem) {
  .history-lead-card {
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
  }
  .plan-flow-steps--five {
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 6rem), 1fr));
  }
  .plan-condition-summary,
  .screen--plan .field-grid--two {
    grid-template-columns: repeat(auto-fit, minmax(min(100%, 14rem), 1fr));
  }
}
.segmented-control {
  min-width: 0;
  max-width: 100%;
}
.segmented-control > * {
  min-width: 0;
}


/* 数値、日付、グラフラベル、レポート数値 */
:is(
  .feature-link-card__number,
  .home-start-steps li > span,
  .numbered-detail-card__number,
  .history-period-tab,
  .history-count-grid dd,
  .weekly-load-comparison strong,
  .history-timeline time,
  .recent-comparison-values dd,
  .body-part-share-comparison__values dd,
  .body-part-share-trend text,
  .history-calendar__date,
  .history-chart-scroll svg,
  .history-chart-data :is(th, td),
  .plan-load-summary > strong,
  .plan-condition-row dd strong,
  .plan-final-heading strong,
  .saved-plan-conditions dd,
  .report-fact-list dd,
  .report-notes-list dd,
  .report-model-total > strong
) {
  font-family: var(--font-numeric);
  font-variant-numeric: tabular-nums lining-nums;
  font-feature-settings: "tnum" 1, "lnum" 1;
}
:is(
  .history-count-grid dd,
  .weekly-load-comparison strong,
  .recent-comparison-values dd,
  .body-part-share-comparison__values dd,
  .plan-condition-row dd strong,
  .plan-final-heading strong,
  .saved-plan-conditions dd,
  .report-fact-list dd,
  .report-notes-list dd
) {
  font-weight: 800;
}
.history-chart__grid text,
.history-chart__date-label,
.history-chart__rest-label {
  font-family: var(--font-numeric);
  font-variant-numeric: tabular-nums lining-nums;
  font-feature-settings: "tnum" 1, "lnum" 1;
  font-size: 12px;
  font-weight: 750;
}

/* コース条件を記録本体から独立した再利用用ライブラリとして扱う */
.course-library-panel {
  display: grid;
  gap: var(--space-4);
  padding: clamp(1rem, 3vw, 1.5rem);
  border: 2px solid var(--color-line);
  border-radius: var(--radius-large);
  background: var(--color-surface);
  box-shadow: var(--shadow-card);
}
.course-library-panel__heading {
  display: flex;
  flex-wrap: wrap;
  align-items: start;
  justify-content: space-between;
  gap: var(--space-3);
}
.course-library-panel__heading p {
  margin-bottom: var(--space-1);
  color: var(--color-accent);
  font-size: 0.75rem;
  font-weight: 850;
  letter-spacing: 0.12em;
}
.course-library-panel__heading h3 { margin: 0; font-family: var(--font-editorial); font-size: clamp(1.2rem, 4vw, 1.65rem); }
.course-library-count {
  padding: 0.3rem 0.65rem;
  border-radius: 999px;
  background: var(--color-accent-soft);
  color: var(--color-accent-strong);
  font-size: 0.82rem;
  font-weight: 800;
}
.course-library-controls { display: grid; gap: var(--space-3); }
.course-library-actions { display: flex; flex-wrap: wrap; gap: var(--space-2); }
.course-library-actions .button { flex: 1 1 12rem; }
.course-library-status {
  min-height: 1.5em;
  margin: 0;
  color: var(--color-muted);
  font-weight: 700;
}
.course-library-status[data-tone="success"] { color: var(--color-success); }
.course-library-status[data-tone="error"] { color: var(--color-danger); }
@media (min-width: 48rem) {
  .course-library-controls { grid-template-columns: minmax(14rem, 0.85fr) minmax(0, 1.15fr); align-items: end; }
}
@media (max-width: 35rem) {
  .course-library-actions { display: grid; grid-template-columns: 1fr; }
  .course-library-actions .button { width: 100%; }
}
@media print {
  .course-library-panel { display: none !important; }
}

/* コース選択・管理を記録フォームから分離 */
.record-course-entry,
.course-manager-introduction,
.course-manager-card {
  display: grid;
  gap: var(--space-4);
  padding: var(--space-5);
  border: 2px solid var(--color-line-strong, var(--color-line));
  border-radius: var(--radius-medium);
  background: var(--color-surface);
  box-shadow: var(--shadow-card);
}
.record-course-entry__heading,
.course-manager-introduction {
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: start;
}
.record-course-entry__heading { display: flex; justify-content: space-between; gap: var(--space-4); }
.record-course-entry__heading p,
.course-manager-introduction > div > p {
  margin: 0 0 var(--space-1);
  color: var(--color-accent-strong);
  font-family: var(--font-numeric);
  font-weight: 800;
  letter-spacing: .08em;
  font-size: .78rem;
}
.record-course-entry__heading h3,
.course-manager-introduction h2 { margin: 0; }
.record-course-entry__actions,
.course-manager-card__actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-3);
}
.record-course-entry__actions .button { min-width: min(100%, 14rem); }
.course-summary { display: grid; gap: var(--space-2); }
.course-summary :is(h2,h3,h4) { margin: 0; font-family: var(--font-editorial); }
.course-summary p { margin: 0; color: var(--color-muted); }
.course-summary p strong { color: var(--color-ink); }
.course-summary--compact {
  padding: var(--space-4);
  border-radius: var(--radius-small);
  background: var(--color-surface-muted);
}
.course-manager-introduction { margin-bottom: var(--space-6); }
.course-manager-introduction .button { align-self: center; }
.course-card-grid { display: grid; gap: var(--space-4); grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr)); }
.course-manager-card { box-shadow: none; }
.course-manager-card__actions { margin-top: auto; }
.course-manager-card__actions .button { flex: 1 1 9rem; }
.course-manager-boundary { margin-top: var(--space-4); color: var(--color-muted); }
.course-editor-form { gap: var(--space-6); }
.course-editor-form .form-section { display: grid; gap: var(--space-4); }
.screen--course-library .context-navigation,
.screen--course-editor .context-navigation { margin-bottom: var(--space-4); }

@media (max-width: 700px) {
  .record-course-entry,
  .course-manager-introduction,
  .course-manager-card { padding: var(--space-4); }
  .course-manager-introduction { grid-template-columns: 1fr; }
  .record-course-entry__actions,
  .course-manager-card__actions { display: grid; grid-template-columns: 1fr; }
  .record-course-entry__actions :is(.button,.text-link),
  .course-manager-card__actions .button { width: 100%; }
}

@media print {
  .screen--course-library,
  .screen--course-editor { display: none !important; }
}

/* 今回の身体記録を記録フォームから分離し、人体図入力へ接続 */
.record-subjective-entry,
.record-personal-entry {
  display: grid;
  gap: var(--space-4);
  padding: var(--space-5);
  border: 2px solid var(--color-line-strong, var(--color-line));
  border-radius: var(--radius-medium);
  background: var(--color-surface);
  box-shadow: var(--shadow-card);
}
.record-subjective-entry__heading {
  display: flex;
  justify-content: space-between;
  align-items: start;
  gap: var(--space-4);
}
.record-subjective-entry__heading p,
.subjective-body-part-panel__heading p {
  margin: 0 0 var(--space-1);
  color: var(--color-accent-strong);
  font-family: var(--font-numeric);
  font-size: .78rem;
  font-weight: 800;
  letter-spacing: .08em;
}
.record-subjective-entry__heading h3,
.subjective-body-part-panel__heading h3 { margin: 0; }
.record-subjective-entry__summary { margin: 0; font-weight: 800; }
.record-subjective-entry__actions { display: flex; flex-wrap: wrap; gap: var(--space-3); }
.record-subjective-entry__actions .button { min-width: min(100%, 14rem); }

.subjective-boundary-notice { margin-bottom: var(--space-5); }
.subjective-body-entry__layout { display: grid; gap: var(--space-5); align-items: start; }
.subjective-body-entry__selector,
.subjective-body-entry__details { min-width: 0; display: grid; gap: var(--space-4); }
.subjective-body-map { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: var(--space-3); }
.subjective-body-map__view { min-width: 0; margin: 0; text-align: center; }
.subjective-body-map__view figcaption { margin-bottom: var(--space-2); font-weight: 800; }
.subjective-body-map__view svg { width: 100%; max-height: 23rem; overflow: visible; }
.subjective-body-map__region-link { cursor: pointer; outline: none; }
.subjective-body-map__region {
  fill: var(--color-map-low);
  stroke: var(--color-map-line);
  stroke-width: 4;
  transition: fill 120ms ease, stroke 120ms ease, stroke-width 120ms ease;
}
.subjective-body-map__region.is-selected { fill: var(--color-map-middle); stroke: var(--color-focus); stroke-width: 7; }
.subjective-body-map__region.is-active,
.subjective-body-map__region-link:hover .subjective-body-map__region,
.subjective-body-map__region-link:focus-visible .subjective-body-map__region { fill: var(--color-map-middle); stroke: var(--color-focus); stroke-width: 9; }
.subjective-body-map__region-link .body-map__touch-band { fill: transparent; pointer-events: none; }
.subjective-body-part-chips { display: grid; grid-template-columns: repeat(auto-fit, minmax(min(100%, 9rem), 1fr)); gap: var(--space-2); }
.subjective-body-part-chip {
  min-height: var(--touch-target);
  padding: .7rem .8rem;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-small);
  background: var(--color-surface);
  color: var(--color-ink);
  font: inherit;
  font-weight: 800;
  text-align: left;
  cursor: pointer;
}
.subjective-body-part-chip:hover,
.subjective-body-part-chip:focus-visible,
.subjective-body-part-chip.is-active { border-color: var(--color-focus); outline: 2px solid transparent; }
.subjective-body-part-chip.is-selected { border-color: var(--color-accent); background: var(--color-accent-soft); color: var(--color-accent-strong); }
.subjective-selection-summary {
  display: grid;
  gap: var(--space-1);
  margin: 0;
  padding: var(--space-4);
  border-radius: var(--radius-small);
  background: var(--color-surface-muted);
}
.subjective-selection-summary span { color: var(--color-muted); }
.subjective-area-groups { display: grid; gap: var(--space-3); }
.subjective-area-group {
  border: 1px solid var(--color-line);
  border-radius: var(--radius-medium);
  background: var(--color-surface);
}
.subjective-area-group > summary {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: var(--space-3);
  padding: var(--space-4);
  cursor: pointer;
  list-style: none;
}
.subjective-area-group > summary::-webkit-details-marker { display: none; }
.subjective-area-group > summary > span:first-child { display: grid; gap: var(--space-1); }
.subjective-area-group > summary small { color: var(--color-muted); }
.subjective-area-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 15rem), 1fr));
  gap: var(--space-2);
  padding: 0 var(--space-4) var(--space-4);
}
.subjective-area-field {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--space-3);
  min-height: 4.5rem;
  padding: var(--space-3);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-small);
  background: var(--color-surface-soft);
}
.subjective-area-field > span { display: grid; gap: var(--space-1); min-width: 0; }
.subjective-area-field small { color: var(--color-muted); font-size: 0.72rem; }
.subjective-area-field select { min-width: 7.5rem; font-family: var(--font-numeric); font-weight: 800; }
.subjective-area-field__controls {
  display: grid;
  grid-template-columns: repeat(2, minmax(7.5rem, auto));
  gap: var(--space-2);
}
.subjective-area-field__controls label { display: grid; gap: var(--space-1); }
.subjective-area-field__controls label > span { color: var(--color-muted); font-size: 0.75rem; font-weight: 700; }
.subjective-area-field.is-selected {
  border-color: var(--color-accent);
  background: var(--color-accent-soft);
}
.subjective-body-part-panel {
  display: grid;
  gap: var(--space-4);
  padding: var(--space-5);
  border: 2px solid var(--color-line);
  border-radius: var(--radius-medium);
  background: var(--color-surface);
}
.subjective-body-part-panel__heading { display: flex; justify-content: space-between; align-items: start; gap: var(--space-4); }
.subjective-score-fields select { font-family: var(--font-numeric); font-variant-numeric: tabular-nums lining-nums; font-weight: 800; }

@media (min-width: 64rem) {
  .subjective-body-entry__layout { grid-template-columns: repeat(auto-fit, minmax(min(100%, 22rem), 1fr)); }
  .subjective-body-entry__details { position: sticky; top: var(--space-4); }
}
@media (max-width: 700px) {
  .record-subjective-entry,
  .subjective-body-part-panel { padding: var(--space-4); }
  .record-subjective-entry__actions { display: grid; grid-template-columns: 1fr; }
  .record-subjective-entry__actions .button { width: 100%; }
  .subjective-body-map { grid-template-columns: 1fr 1fr; }
  .subjective-body-map__view:last-child { grid-column: 1 / -1; width: 50%; justify-self: center; }
  .subjective-area-field { grid-template-columns: 1fr; }
  .subjective-area-field__controls { grid-template-columns: 1fr; }
  .subjective-area-field select { width: 100%; }
}
@media (hover: none), (pointer: coarse) {
  .subjective-body-map__region-link .subjective-body-map__region { pointer-events: none; }
  .subjective-body-map__region-link .body-map__touch-band { pointer-events: all; }
}
@media (prefers-reduced-motion: reduce) {
  .subjective-body-map__region { transition: none; }
}
@media (forced-colors: active) {
  .subjective-body-map__region-link,
  .subjective-body-map__region,
  .subjective-body-part-chip { forced-color-adjust: auto; }
  .subjective-body-map__region.is-selected { fill: Highlight; stroke: HighlightText; }
  .subjective-body-map__region.is-active,
  .subjective-body-map__region-link:focus-visible .subjective-body-map__region { stroke: Highlight; }
  .subjective-body-part-chip.is-selected { border: 3px solid Highlight; }
}

/* 入力補助画面との往復状態と要約表示 */
.record-optional-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));
  gap: var(--space-5);
  align-items: stretch;
}
.record-optional-grid > section { min-width: 0; height: 100%; }
.home-compact-card .button { justify-self: start; min-height: 2.75rem; padding: var(--space-2) var(--space-4); }
.record-return-status {
  margin: 0;
  padding: var(--space-3) var(--space-4);
  border-left: 4px solid var(--color-accent);
  border-radius: var(--radius-small);
  background: var(--color-accent-soft);
  color: var(--color-accent-strong);
  font-weight: 800;
}
#record-course-entry,
#record-subjective-entry,
#record-optional-title { scroll-margin-top: 6rem; }
@media (max-width: 700px) {
  .record-optional-grid { grid-template-columns: 1fr; gap: var(--space-4); }
}
@media (forced-colors: active) {
  .record-return-status { border-color: Highlight; }
}
@media print {
  .record-return-status { display: none !important; }
}

/* UI-FEEDBACK3: result screen summary, recent average, and minimal personal note */
.result-helper-text {
  margin-bottom: 0;
  color: var(--color-muted);
  font-size: 0.95rem;
}
.recent-comparison-values--three { grid-template-columns: repeat(3, minmax(0, 1fr)); }
.model-total-trend {
  display: grid;
  gap: var(--space-2);
  margin: 0;
}
.model-total-trend figcaption {
  font-weight: 850;
}
.model-total-trend svg {
  width: 100%;
  height: auto;
  border: 1px solid var(--color-line);
  border-radius: var(--radius-medium);
  background: var(--color-paper);
}
.model-total-trend__average {
  stroke: var(--color-line-strong);
  stroke-dasharray: 5 5;
  stroke-width: 1.5;
}
.model-total-trend__line {
  fill: none;
  stroke: var(--color-accent);
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;
}
.model-total-trend__point {
  fill: var(--color-surface);
  stroke: var(--color-accent);
  stroke-width: 2;
}
.model-total-trend__point.is-current {
  fill: var(--color-accent);
}
.model-total-trend text {
  fill: var(--color-muted);
  font-size: 0.72rem;
  font-family: var(--font-numeric);
}
.model-total-trend p {
  margin-bottom: 0;
  color: var(--color-muted);
  font-size: 0.92rem;
}
@media (max-width: 35rem) {
  .recent-comparison-values--three { grid-template-columns: 1fr; }
}
@media (forced-colors: active) {
  .model-total-trend svg { border-color: CanvasText; }
  .model-total-trend__line,
  .model-total-trend__point,
  .model-total-trend__average { stroke: CanvasText; }
  .model-total-trend__point.is-current { fill: CanvasText; }
}

/* UI-FEEDBACK5: history finder and weekly summary role separation */
.history-lead-card--finder { border-left-color: var(--color-ink); }
.history-picker-list {
  display: grid;
  gap: var(--space-3);
}
.history-picker-item {
  display: grid;
  gap: var(--space-3);
  padding: var(--space-4);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-small);
  background: var(--color-surface);
}
.history-picker-item__main {
  display: grid;
  gap: var(--space-2);
}
.history-picker-item__main time {
  color: var(--color-muted);
  font-weight: 850;
}
.history-picker-item__main h3 { margin: 0; }
.history-picker-item__main p { margin: 0; color: var(--color-muted); }
.history-picker-item__actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2);
  align-items: center;
}
@media (min-width: 50rem) {
  .history-picker-item {
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: center;
  }
  .history-picker-item__actions {
