.history-calendar {
  min-width: 46rem;
  grid-template-columns: repeat(7, minmax(5.75rem, 1fr));
}
.history-calendar__day-content {
  align-content: start;
  gap: 0.45rem;
  padding: 0.72rem;
}
.history-calendar__date {
  display: grid;
  grid-template-columns: 1fr;
  justify-items: start;
  gap: 0.18rem;
  min-width: 0;
}
.history-calendar__date time {
  display: inline-block;
