.regional-view-tabs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-2);
  padding: var(--space-2);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-medium);
  background: var(--color-neutral-soft);
}
.regional-view-tabs button {
  min-width: 0;
  min-height: var(--touch-target);
  padding: var(--space-3);
  border: 1px solid transparent;
  border-radius: calc(var(--radius-medium) - 4px);
  background: transparent;
  color: var(--color-ink);
  font: inherit;
  font-weight: 800;
  line-height: 1.35;
  cursor: pointer;
}
.regional-view-tabs button[aria-selected="true"] {
  border-color: var(--color-accent);
  background: var(--color-surface);
  color: var(--color-accent-strong);
  box-shadow: 0 3px 10px color-mix(in srgb, var(--color-ink) 8%, transparent);
}
.regional-view-tabs button:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
}
.regional-view-panel {
  display: grid;
  gap: var(--space-5);
}
.regional-view-panel[hidden] { display: none; }
.regional-view-panel__heading {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--space-4);
  padding-bottom: var(--space-4);
  border-bottom: 1px solid var(--color-line);
}
.regional-view-panel__heading p {
  max-width: 52rem;
  margin: var(--space-2) 0 0;
  color: var(--color-muted);
}
.v27-body-map {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: var(--space-3);
  padding: var(--space-4);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-medium);
  background: color-mix(in srgb, var(--color-surface) 86%, var(--color-accent-soft));
}
.v27-body-map__view {
  min-width: 0;
  margin: 0;
  text-align: center;
}
.v27-body-map__view figcaption {
  margin-bottom: var(--space-2);
  font-weight: 800;
}
.v27-body-map__view svg {
  width: 100%;
  max-height: 23rem;
}
.v27-body-map__region {
  fill: var(--color-accent);
  fill-opacity: 0.55;
  stroke: var(--color-surface);
  stroke-width: 3;
}
.regional-v2-map .v27-body-map__region[data-direction="above"] { fill: var(--color-accent); }
.regional-v2-map .v27-body-map__region[data-direction="reference"] { fill: var(--color-model); }
.regional-v2-map .v27-body-map__region[data-direction="below"] { fill: var(--color-info); }
.regional-v2-map .v27-body-map__region[data-direction="unavailable"] {
  fill: var(--color-muted);
  fill-opacity: 0.2;
}
.regional-direction-legend {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-2) var(--space-4);
  margin: 0;
  padding: 0;
  color: var(--color-muted);
  list-style: none;
}
.regional-direction-legend li {
  display: inline-flex;
  gap: var(--space-2);
  align-items: center;
}
.regional-direction-legend span {
  width: 1.7rem;
  height: 1.7rem;
  display: inline-grid;
  place-items: center;
  border: 1px solid var(--color-line);
  border-radius: 50%;
  color: var(--color-ink);
  font-weight: 900;
}
.v27-body-map__region.is-context {
  fill: none;
  stroke: var(--color-model);
  stroke-width: 5;
  stroke-dasharray: 10 7;
}
.regional-result-list {
  display: grid;
  gap: var(--space-4);
}
.regional-result-list__numeric,
.regional-context-list {
  display: grid;
  gap: var(--space-2);
  margin: 0;
  padding: 0;
  list-style: none;
}
.regional-result-row a {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto;
  gap: var(--space-2) var(--space-4);
  min-width: 0;
  padding: var(--space-4);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-medium);
  color: inherit;
  text-decoration: none;
}
.regional-result-row a:hover,
.regional-result-row a:focus-visible {
  border-color: var(--color-accent);
  background: var(--color-accent-soft);
}
.regional-result-row a:focus-visible {
  outline: 3px solid var(--color-focus);
  outline-offset: 2px;
}
.regional-result-row__name strong,
.regional-result-row__name small,
.regional-result-row__value strong,
.regional-result-row__value small {
  display: block;
}
.regional-result-row__name small,
.regional-result-row__value small,
.regional-result-row__personal {
  color: var(--color-muted);
  font-size: 0.78rem;
}
.regional-result-row__value {
  min-width: 4.5rem;
  text-align: right;
}
.regional-result-row__value strong {
  font-family: var(--font-numeric);
  font-size: 1.75rem;
  line-height: 1;
}
.regional-result-row__building {
  display: inline-block;
  max-width: 9rem;
  color: var(--color-muted);
  font-size: 0.85rem;
  font-weight: 800;
}
.regional-result-row__direction,
.regional-result-row__personal,
.regional-result-row__chips,
.regional-result-row__scale {
  grid-column: 1 / -1;
}
.regional-result-row__direction {
  color: var(--color-muted);
  font-size: 0.86rem;
  font-weight: 750;
}
.regional-result-row__scale {
  position: relative;
  height: 0.75rem;
  border-radius: 999px;
  background: var(--color-meter-track);
}
.regional-result-row__scale i {
  position: absolute;
  top: -0.2rem;
  bottom: -0.2rem;
  left: 50%;
  width: 2px;
  background: var(--color-ink);
}
.regional-result-row__scale b {
  position: absolute;
  top: 50%;
  left: var(--regional-position);
  width: 0.85rem;
  height: 0.85rem;
  border: 2px solid var(--color-surface);
  border-radius: 50%;
  background: var(--color-accent);
  transform: translate(-50%, -50%);
}
.regional-result-row__chips {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-1);
}
.regional-result-row__chips small {
  padding: 0.2rem 0.45rem;
  border: 1px solid var(--color-line);
  border-radius: 999px;
  background: var(--color-neutral-soft);
  color: var(--color-muted);
  font-size: 0.72rem;
}
.regional-context-list li {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-4);
  padding: var(--space-4);
  border: 1px dashed var(--color-model);
  border-radius: var(--radius-medium);
}
.regional-context-list strong,
.regional-context-list small { display: block; }
.regional-context-list small { color: var(--color-muted); }
.regional-context-list li > span:last-child {
  color: var(--color-model);
  font-weight: 800;
  text-align: right;
}
.regional-view-unavailable {
  padding: var(--space-5);
  border: 1px dashed var(--color-line);
  border-radius: var(--radius-medium);
  background: var(--color-neutral-soft);
}
.regional-view-unavailable p {
  margin: var(--space-2) 0 0;
  color: var(--color-muted);
}
.regional-claim-boundary {
  border-top: 1px solid var(--color-line);
  padding-top: var(--space-4);
}
.regional-claim-boundary summary {
  min-height: var(--touch-target);
  font-weight: 800;
  cursor: pointer;
}
.regional-claim-boundary div {
  display: grid;
  gap: var(--space-2);
  padding-top: var(--space-3);
  color: var(--color-muted);
}
.regional-claim-boundary p { margin: 0; }
.total-primary-range {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: var(--space-2);
  margin: 0;
}
.total-primary-range strong {
  font-family: var(--font-numeric);
  font-size: 1.65rem;
}
.total-primary-range span { color: var(--color-muted); }
.subjective-internal-response {
  padding: var(--space-4);
  border: 1px solid var(--color-line);
  border-radius: var(--radius-medium);
  background: var(--color-info-soft);
}
.subjective-internal-response h3,
.subjective-internal-response p { margin-bottom: var(--space-1); }
.subjective-internal-response strong {
  font-family: var(--font-numeric);
  font-size: 1.5rem;
}
.subjective-internal-response small { color: var(--color-muted); }
.derived-course-fact {
  margin: var(--space-3) 0 0;
  padding: var(--space-3);
  border-left: 4px solid var(--color-accent);
  background: var(--color-accent-soft);
  font-weight: 800;
}

@media (min-width: 58rem) {
  .regional-view-panel:not([hidden]) {
    grid-template-columns: minmax(18rem, 0.8fr) minmax(24rem, 1.2fr);
    align-items: start;
  }
  .regional-view-panel__heading,
  .regional-view-unavailable,
  .regional-claim-boundary {
    grid-column: 1 / -1;
  }
}

@media (max-width: 42rem) {
  .regional-view-tabs { grid-template-columns: 1fr; }
  .regional-view-panel__heading { display: grid; }
  .v27-body-map { grid-template-columns: 1fr 1fr; }
  .v27-body-map__view:last-child {
    grid-column: 1 / -1;
    width: 50%;
    justify-self: center;
  }
  .regional-context-list li { align-items: flex-start; }
}

@media (max-width: 22rem) {
  .v27-body-map { grid-template-columns: 1fr; }
  .v27-body-map__view:last-child {
    grid-column: auto;
    width: 100%;
  }
  .regional-result-row a { grid-template-columns: minmax(0, 1fr); }
  .regional-result-row__value { text-align: left; }
  .regional-context-list li { display: grid; }
  .regional-context-list li > span:last-child { text-align: left; }
}

@media (prefers-reduced-motion: reduce) {
  .regional-view-tabs button,
  .regional-result-row a,
  .regional-result-row__scale b { transition: none !important; }
}

@media (forced-colors: active) {
  .v27-body-map__region { fill: CanvasText; stroke: Canvas; }
  .v27-body-map__region.is-context { fill: none; stroke: CanvasText; }
  .regional-result-row__scale b,
  .regional-result-row__scale i { background: CanvasText; }
}

@media print {
  .regional-view-tabs { display: none; }
  .regional-view-panel:not([hidden]) { display: grid; }
  .regional-result-row a { color: inherit; text-decoration: none; }
}


